package dev.industrialtechnology.spacecheck;
import java.util.*;import java.util.function.BiConsumer;import net.minecraft.world.*;import net.minecraft.entity.player.*;import net.minecraft.entity.item.EntityItem;import net.minecraft.init.*;import net.minecraft.item.*;import net.minecraft.item.crafting.*;import net.minecraft.block.Block;import net.minecraft.nbt.*;import net.minecraftforge.common.*;import net.minecraftforge.common.util.*;import net.minecraftforge.event.world.BlockEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import dev.industrialtechnology.space.*;
public final class ShuttleChecks {
    private static void check(boolean b,String s){SpaceChecks.check(b,s);}
    private static TileLaunchFacility root(WorldServer w,EntityPlayerMP p,int x){w.getChunkFromChunkCoords(x>>4,400>>4);w.setBlock(x,6,400,LaunchFacilityRegistry.facility,3,3);TileLaunchFacility t=(TileLaunchFacility)w.getTileEntity(x,6,400);t.owner=p.getUniqueID().toString();return t;}
    private static void partiallyBuild(TileLaunchFacility t){int calls=0;while(t.phase==0&&calls++<1500){FacilityIndex.budget=512;t.advance();}check(t.phase==1&&t.cursor>0&&t.cursor<=256,"partial fixture did not pass real preflight: "+t.status);}
    private static void build(TileLaunchFacility t){int n=0;while(t.phase<2&&n++<1500){FacilityIndex.budget=512;t.advance();}check(t.phase==2,"Deployment failed: "+t.status+" phase="+t.phase);}
    private static int parts(WorldServer w,TileLaunchFacility t){int n=0;for(LaunchFacilityPlan.Cell c:LaunchFacilityPlan.CELLS)if(w.getBlock(t.worldX(c.x,c.z),t.yCoord+c.y,t.worldZ(c.x,c.z))==LaunchFacilityRegistry.part)n++;return n;}
    public static final class Denial {public boolean active;@SubscribeEvent public void place(BlockEvent.PlaceEvent e){if(active)e.setCanceled(true);}@SubscribeEvent public void breaking(BlockEvent.BreakEvent e){if(active)e.setCanceled(true);}}
    public static void run(WorldServer w,WorldServer moon,EntityPlayerMP p,BiConsumer<String,Runnable> test){
        test.accept("New assembly selects full-scale Shuttle; legacy choice and NBT remain distinct",()->{TileSpaceMachine a=new TileSpaceMachine(SpaceRegistry.ASSEMBLY);a.setWorldObj(w);a.energy=100000;for(int i=0;i<11;i++)a.items[i]=new ItemStack(SpaceRegistry.parts[i]);a.assemble();check(ShuttleVehicle.is(a.items[11])&&a.energy==50000,"Shuttle blueprint default");a.items[11]=null;a.target=0;for(int i=0;i<11;i++)a.items[i]=new ItemStack(SpaceRegistry.parts[i]);a.assemble();check(!ShuttleVehicle.is(a.items[11]),"legacy choice lost");NBTTagCompound old=new NBTTagCompound();old.setInteger("Kind",SpaceRegistry.ASSEMBLY);a.readFromNBT(old);check(a.target==0,"old station changed type");});
        test.accept("Metre-scale LC39 kit deploys all parts in checked batches without one TE per block",()->{TileLaunchFacility t=root(w,p,400);FacilityIndex.get(w).reserve(t);FacilityIndex.budget=512;t.advance();check(t.phase==0&&t.cursor==0&&t.preparedChunks<=2,"chunk preparation exceeded batch");build(t);check(t.intact()&&parts(w,t)==LaunchFacilityPlan.CELLS.size(),"missing structure parts");for(LaunchFacilityPlan.Cell c:LaunchFacilityPlan.CELLS)check(w.getTileEntity(t.worldX(c.x,c.z),6+c.y,t.worldZ(c.x,c.z))==null,"part has ticking TE");t.items[0]=SpaceChecks.rocket();t.items[0].getTagCompound().setBoolean("Shuttle",true);t.items[1]=new ItemStack(SpaceRegistry.hdd);NBTTagCompound research=new NBTTagCompound();research.setInteger("MoonTicks",SpaceConfig.moonResearch);research.setInteger("MarsTicks",SpaceConfig.marsResearch);t.items[1].setTagCompound(research);t.tanks[0].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.kerosene,30000),true);t.tanks[1].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.lox,60000),true);check(RocketTravel.ready(RocketTravel.check(t,null)),RocketTravel.check(t,null));w.setBlock(t.shipX()+12,t.shipY()+50,t.shipZ(),Blocks.stone,0,3);check(!RocketTravel.clear(t),"high wing obstruction ignored");w.setBlockToAir(t.shipX()+12,t.shipY()+50,t.shipZ());ShuttleVehicle.attach(t);EntitySpaceRocket e=new EntitySpaceRocket(w);NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n);e.control.readFromNBT(n);e.control.xCoord=t.shipX();e.control.yCoord=t.shipY()-1;e.control.zCoord=t.shipZ();e.updateGeometry();check(e.height==56.1f&&e.width==24&&e.getMountedYOffset()==43,"ship geometry");check(RocketTravel.pad(e.control)&&RocketTravel.clear(e.control),"copied flight origin geometry");t.markDirty();});
        test.accept("Occupied-cell preflight preserves builds and returns exactly one unbuilt kit",()->{TileLaunchFacility t=root(w,p,650);w.setBlock(t.worldX(-59,-74),5,t.worldZ(-59,-74),Blocks.diamond_block,0,3);FacilityIndex.get(w).reserve(t);int scans=0;while(t.phase==0&&scans++<100){FacilityIndex.budget=512;t.advance();}check(t.phase==3,"occupied cell accepted");FacilityIndex.budget=512;FacilityIndex.tick(w);check(w.getBlock(591,5,326)==Blocks.diamond_block,"existing build overwritten");check(w.isAirBlock(650,6,400),"aborted root not removed");});
        test.accept("Overlapping kit cannot dismantle another facility",()->{TileLaunchFacility t=root(w,p,420);t.updateEntity();check(t.phase==3,"overlap accepted");FacilityIndex.budget=512;FacilityIndex.tick(w);TileLaunchFacility original=(TileLaunchFacility)w.getTileEntity(400,6,400);check(original!=null&&original.phase==2&&parts(w,original)==LaunchFacilityPlan.CELLS.size(),"overlap rollback removed original blocks");});
        test.accept("Forge placement cancellation rolls back parts; recovery respects break protection",()->{TileLaunchFacility t=root(w,p,950);FacilityIndex.get(w).reserve(t);t.phase=1;t.cursor=0;Denial d=new Denial();MinecraftForge.EVENT_BUS.register(d);try{d.active=true;FacilityIndex.budget=512;t.advance();check(t.phase==3&&parts(w,t)==0,"denied part retained");FacilityIndex.budget=512;FacilityIndex.tick(w);check(w.getTileEntity(950,6,400)==t,"protected root removed");d.active=false;FacilityIndex.budget=512;FacilityIndex.tick(w);check(w.isAirBlock(950,6,400),"recovery did not resume");}finally{MinecraftForge.EVENT_BUS.unregister(d);}});
        test.accept("Construction and cleanup cursors persist for real server restart",()->{TileLaunchFacility t=root(w,p,1200);FacilityIndex.get(w).reserve(t);partiallyBuild(t);t.items[1]=new ItemStack(SpaceRegistry.hdd);t.markDirty();TileLaunchFacility c=root(w,p,1450);FacilityIndex.get(w).reserve(c);partiallyBuild(c);for(int i=0;i<4;i++){FacilityIndex.budget=512;c.advance();}c.tanks[0].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.kerosene,1234),true);c.dismantle("save cleanup");FacilityIndex.budget=512;FacilityIndex.tick(w);check(c.phase==3&&parts(w,c)>0,"cleanup was not partial");});
        test.accept("Both planets generate deterministic, body-specific mineable minerals and finite ice water recipe",()->{for(int dim:new int[]{SpaceConfig.moon,SpaceConfig.mars}){WorldServer planet=RocketTravel.world(dim);int[] count=new int[6];for(int cx=30;cx<34;cx++)for(int cz=30;cz<34;cz++){net.minecraft.world.chunk.Chunk c=planet.getChunkFromChunkCoords(cx,cz);for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=7;y<190;y++){Block b=c.getBlock(x,y,z);for(int k=0;k<6;k++)if(b==PlanetResources.ORES[k]){count[k]++;check(b.getDrops(planet,cx*16+x,y,cz*16+z,0,0).get(0).getItem()==Item.getItemFromBlock(b),"unmineable mineral");}}}int first=dim==SpaceConfig.moon?0:3;for(int k=0;k<6;k++)check(k>=first&&k<first+3?count[k]>0:count[k]==0,"body mineral mapping "+k+" count="+count[k]);}check(FurnaceRecipes.smelting().getSmeltingResult(new ItemStack(PlanetResources.ORES[0])).getItem()==Items.iron_ingot,"lunar iron recipe");check(FurnaceRecipes.smelting().getSmeltingResult(new ItemStack(PlanetResources.ORES[3])).getItem()==Items.iron_ingot,"mars iron recipe");boolean water=false;for(Object o:CraftingManager.getInstance().getRecipeList()){ItemStack out=((IRecipe)o).getRecipeOutput();if(out!=null&&out.getItem()==Items.water_bucket)water=true;}check(water,"no ice water recipe");});
        if(cpw.mods.fml.common.Loader.isModLoaded("hbm"))ShuttleHbmChecks.run(w,p,test);
    }
    public static void restart(WorldServer w,EntityPlayerMP p,BiConsumer<String,Runnable> test){test.accept("LC39 structure, Shuttle marker and independent propellant tanks survive real restart",()->{w.getChunkFromChunkCoords(25,25);TileLaunchFacility t=(TileLaunchFacility)w.getTileEntity(400,6,400);for(LaunchFacilityPlan.Cell c:LaunchFacilityPlan.CELLS)w.getChunkFromChunkCoords(t.worldX(c.x,c.z)>>4,t.worldZ(c.x,c.z)>>4);check(t.phase==2&&ShuttleVehicle.is(t)&&t.tanks[0].getFluidAmount()==30000&&t.tanks[1].getFluidAmount()==60000,"facility NBT lost");check(t.intact()&&parts(w,t)==LaunchFacilityPlan.CELLS.size(),"structure changed on restart");});test.accept("Restart resumes partial construction and exactly-once dismantling with retained contents",()->{w.getChunkFromChunkCoords(1200>>4,400>>4);TileLaunchFacility t=(TileLaunchFacility)w.getTileEntity(1200,6,400);check(t.phase==1&&t.cursor>0&&t.cursor<=256&&t.preparedChunks>0&&t.items[1]!=null,"construction cursor lost");build(t);check(t.phase==2&&t.items[1]!=null,"build resume failed");w.getChunkFromChunkCoords(1450>>4,400>>4);int loops=0;while(w.getBlock(1450,6,400)==LaunchFacilityRegistry.facility&&loops++<100){FacilityIndex.budget=512;FacilityIndex.tick(w);}check(w.isAirBlock(1450,6,400),"cleanup resume failed");int kits=0;for(Object o:w.loadedEntityList)if(o instanceof EntityItem){EntityItem e=(EntityItem)o;ItemStack s=e.getEntityItem();if(s.getItem()==Item.getItemFromBlock(LaunchFacilityRegistry.facility)&&Math.abs(e.posX-1450)<4){kits++;check(s.getTagCompound().getCompoundTag("Controller").getCompoundTag("Tank0").getInteger("Amount")==1234,"kit lost tank");}}check(kits==1,"expected one recovery kit got "+kits);FacilityIndex.budget=512;FacilityIndex.tick(w);});}
}
